import {
  CamelCase,
  ConstantCase,
  DelimiterCase,
  KebabCase,
  PascalCase,
  SnakeCase,
  toCamelCase,
  toConstantCase,
  toDelimiterCase,
  toKebabCase,
  toPascalCase,
  toSnakeCase,
} from './casing'
import { typeOf } from './internals'
import { Is } from './utils'

/**
 * This function is used to transform the keys of an object deeply.
 * It will only be transformed at runtime, so it's not type safe.
 * @param obj the object to transform.
 * @param transform the function to transform the keys from string to string.
 * @returns the transformed object.
 * @example deepTransformKeys({ 'foo-bar': { 'fizz-buzz': true } }, toCamelCase)
 * // { fooBar: { fizzBuzz: true } }
 */
function deepTransformKeys<T>(obj: T, transform: (s: string) => string): T {
  if (!['object', 'array'].includes(typeOf(obj))) return obj

  if (Array.isArray(obj)) {
    return obj.map((x) => deepTransformKeys(x, transform)) as T
  }
  const res = {} as T
  for (const key in obj) {
    res[transform(key) as keyof T] = deepTransformKeys(obj[key], transform)
  }
  return res
}

/**
 * Transforms the keys of an Record to camelCase.
 * T: the type of the Record to transform.
 */
type DeepCamelKeys<T> = T extends [any, ...any]
  ? { [I in keyof T]: DeepCamelKeys<T[I]> }
  : T extends (infer V)[]
  ? DeepCamelKeys<V>[]
  : {
      [K in keyof T as CamelCase<Is<K, string>>]: DeepCamelKeys<T[K]>
    }
/**
 * A strongly typed function that recursively transforms the keys of an object to camelCase. The transformation is done both at runtime and type level.
 * @param obj the object to transform.
 * @returns the transformed object.
 * @example deepCamelKeys({ 'foo-bar': { 'fizz-buzz': true } }) // { fooBar: { fizzBuzz: true } }
 */
function deepCamelKeys<T>(obj: T): DeepCamelKeys<T> {
  return deepTransformKeys(obj, toCamelCase) as never
}

/**
 * Transforms the keys of an Record to PascalCase.
 * T: the type of the Record to transform.
 */
type DeepPascalKeys<T> = T extends [any, ...any]
  ? { [I in keyof T]: DeepPascalKeys<T[I]> }
  : T extends (infer V)[]
  ? DeepPascalKeys<V>[]
  : {
      [K in keyof T as PascalCase<Is<K, string>>]: DeepPascalKeys<T[K]>
    }
/**
 * A strongly typed function that recursively transforms the keys of an object to pascal case. The transformation is done both at runtime and type level.
 * @param obj the object to transform.
 * @returns the transformed object.
 * @example deepPascalKeys({ 'foo-bar': { 'fizz-buzz': true } }) // { FooBar: { FizzBuzz: true } }
 */
function deepPascalKeys<T>(obj: T): DeepPascalKeys<T> {
  return deepTransformKeys(obj, toPascalCase) as never
}

/**
 * Transforms the keys of an Record to kebab-case.
 * T: the type of the Record to transform.
 */
type DeepKebabKeys<T> = T extends [any, ...any]
  ? { [I in keyof T]: DeepKebabKeys<T[I]> }
  : T extends (infer V)[]
  ? DeepKebabKeys<V>[]
  : {
      [K in keyof T as KebabCase<Is<K, string>>]: DeepKebabKeys<T[K]>
    }
/**
 * A strongly typed function that recursively transforms the keys of an object to kebab-case. The transformation is done both at runtime and type level.
 * @param obj the object to transform.
 * @returns the transformed object.
 * @example deepKebabKeys({ 'foo-bar': { 'fizz-buzz': true } }) // { 'foo-bar': { 'fizz-buzz': true } }
 */
function deepKebabKeys<T>(obj: T): DeepKebabKeys<T> {
  return deepTransformKeys(obj, toKebabCase) as never
}

/**
 * Transforms the keys of an Record to snake_case.
 * T: the type of the Record to transform.
 */
type DeepSnakeKeys<T> = T extends [any, ...any]
  ? { [I in keyof T]: DeepSnakeKeys<T[I]> }
  : T extends (infer V)[]
  ? DeepSnakeKeys<V>[]
  : {
      [K in keyof T as SnakeCase<Is<K, string>>]: DeepSnakeKeys<T[K]>
    }
/**
 * A strongly typed function that recursively transforms the keys of an object to snake_case. The transformation is done both at runtime and type level.
 * @param obj the object to transform.
 * @returns the transformed object.
 * @example deepSnakeKeys({ 'foo-bar': { 'fizz-buzz': true } }) // { 'foo_bar': { 'fizz_buzz': true } }
 */
function deepSnakeKeys<T>(obj: T): DeepSnakeKeys<T> {
  return deepTransformKeys(obj, toSnakeCase) as never
}

/**
 * Transforms the keys of an Record to CONSTANT_CASE.
 * T: the type of the Record to transform.
 */
type DeepConstantKeys<T> = T extends [any, ...any]
  ? { [I in keyof T]: DeepConstantKeys<T[I]> }
  : T extends (infer V)[]
  ? DeepConstantKeys<V>[]
  : {
      [K in keyof T as ConstantCase<Is<K, string>>]: DeepConstantKeys<T[K]>
    }
/**
 * A strongly typed function that recursively transforms the keys of an object to CONSTANT_CASE. The transformation is done both at runtime and type level.
 * @param obj the object to transform.
 * @returns the transformed object.
 * @example deepConstantKeys({ 'foo-bar': { 'fizz-buzz': true } }) // { FOO_BAR: { FIZZ_BUZZ: true } }
 */
function deepConstantKeys<T>(obj: T): DeepConstantKeys<T> {
  return deepTransformKeys(obj, toConstantCase) as never
}

/**
 * Transforms the keys of an Record to a custom delimiter case.
 * T: the type of the Record to transform.
 * D: the delimiter to use.
 */
type DeepDelimiterKeys<T, D extends string> = T extends [any, ...any]
  ? { [I in keyof T]: DeepDelimiterKeys<T[I], D> }
  : T extends (infer V)[]
  ? DeepDelimiterKeys<V, D>[]
  : {
      [K in keyof T as DelimiterCase<Is<K, string>, D>]: DeepDelimiterKeys<
        T[K],
        D
      >
    }
/**
 * A strongly typed function that recursively transforms the keys of an object to a custom delimiter case. The transformation is done both at runtime and type level.
 * @param obj the object to transform.
 * @param delimiter the delimiter to use.
 * @returns the transformed object.
 * @example deepDelimiterKeys({ 'foo-bar': { 'fizz-buzz': true } }, '.') // { 'foo.bar': { 'fizz.buzz': true } }
 */
function deepDelimiterKeys<T, D extends string>(
  obj: T,
  delimiter: D,
): DeepDelimiterKeys<T, D> {
  return deepTransformKeys(obj, (str) =>
    toDelimiterCase(str, delimiter),
  ) as never
}

export type {
  DeepCamelKeys,
  DeepConstantKeys,
  DeepDelimiterKeys,
  DeepKebabKeys,
  DeepPascalKeys,
  DeepSnakeKeys,
}
export {
  deepCamelKeys,
  deepConstantKeys,
  deepDelimiterKeys,
  deepKebabKeys,
  deepPascalKeys,
  deepSnakeKeys,
  deepTransformKeys,
}

import { PascalCaseAll } from './internals'
import { Join, join } from './primitives'
import { Is, Words, words } from './utils'

// CASING UTILITIES
/**
 * This function is a strongly-typed counterpart of String.prototype.toLowerCase.
 * @param str the string to make lowercase.
 * @returns the lowercased string.
 * @example toLowerCase('HELLO WORLD') // 'hello world'
 */
function toLowerCase<T extends string>(str: T) {
  return str.toLowerCase() as Lowercase<T>
}

/**
 * This function is a strongly-typed counterpart of String.prototype.toUpperCase.
 * @param str the string to make uppercase.
 * @returns the uppercased string.
 * @example toUpperCase('hello world') // 'HELLO WORLD'
 */
function toUpperCase<T extends string>(str: T) {
  return str.toUpperCase() as Uppercase<T>
}

/**
 * Capitalizes the first letter of a string. This is a runtime counterpart of `Capitalize<T>` from `src/types.d.ts`.
 * @param str the string to capitalize.
 * @returns the capitalized string.
 * @example capitalize('hello world') // 'Hello world'
 */
function capitalize<T extends string>(str: T) {
  return (toUpperCase(str.charAt(0)) + str.slice(1)) as Capitalize<T>
}

/**
 * Transforms a string with the specified separator (delimiter).
 */
type DelimiterCase<T extends string, D extends string> = Join<Words<T>, D>
/**
 * A function that transforms a string by splitting it into words and joining them with the specified delimiter.
 * @param str the string to transform.
 * @param delimiter the delimiter to use.
 * @returns the transformed string.
 * @example toDelimiterCase('hello world', '.') // 'hello.world'
 */
function toDelimiterCase<T extends string, D extends string>(
  str: T,
  delimiter: D,
): DelimiterCase<T, D> {
  return join(words(str), delimiter)
}

/**
 * Transforms a string to camelCase.
 */
type CamelCase<T extends string> = T extends unknown
  ? PascalCase<T> extends `${infer first}${infer rest}`
    ? `${Lowercase<first>}${rest}`
    : T
  : never

/**
 * A strongly typed version of `toCamelCase` that works in both runtime and type level.
 * @param str the string to convert to camel case.
 * @returns the camel cased string.
 * @example toCamelCase('hello world') // 'helloWorld'
 */
function toCamelCase<T extends string>(str: T) {
  const res = toPascalCase(str)
  return (res.slice(0, 1).toLowerCase() + res.slice(1)) as CamelCase<T>
}

/**
 * Transforms a string to PascalCase.
 */
type PascalCase<T extends string> = Join<PascalCaseAll<Is<Words<T>, string[]>>>
/**
 * A strongly typed version of `toPascalCase` that works in both runtime and type level.
 * @param str the string to convert to pascal case.
 * @returns the pascal cased string.
 * @example toPascalCase('hello world') // 'HelloWorld'
 */
function toPascalCase<T extends string>(str: T): PascalCase<T> {
  return words(str)
    .map((v) => capitalize(toLowerCase(v)))
    .join('') as PascalCase<T>
}

/**
 * Transforms a string to kebab-case.
 */
type KebabCase<T extends string> = Lowercase<DelimiterCase<T, '-'>>
/**
 * A strongly typed version of `toKebabCase` that works in both runtime and type level.
 * @param str the string to convert to kebab case.
 * @returns the kebab cased string.
 * @example toKebabCase('hello world') // 'hello-world'
 */
function toKebabCase<T extends string>(str: T): KebabCase<T> {
  return toLowerCase(toDelimiterCase(str, '-'))
}

/**
 * Transforms a string to snake_case.
 */
type SnakeCase<T extends string> = Lowercase<DelimiterCase<T, '_'>>
/**
 * A strongly typed version of `toSnakeCase` that works in both runtime and type level.
 * @param str the string to convert to snake case.
 * @returns the snake cased string.
 * @example toSnakeCase('hello world') // 'hello_world'
 */
function toSnakeCase<T extends string>(str: T): SnakeCase<T> {
  return toLowerCase(toDelimiterCase(str, '_'))
}

/**
 * Transforms a string to CONSTANT_CASE.
 */
type ConstantCase<T extends string> = Uppercase<DelimiterCase<T, '_'>>
/**
 * A strongly typed version of `toConstantCase` that works in both runtime and type level.
 * @param str the string to convert to constant case.
 * @returns the constant cased string.
 * @example toConstantCase('hello world') // 'HELLO_WORLD'
 */
function toConstantCase<T extends string>(str: T): ConstantCase<T> {
  return toUpperCase(toDelimiterCase(str, '_'))
}

/**
 * Transforms a string to "Title Case".
 */
type TitleCase<T extends string> = DelimiterCase<PascalCase<T>, ' '>
/**
 * A strongly typed version of `toTitleCase` that works in both runtime and type level.
 * @param str the string to convert to title case.
 * @returns the title cased string.
 * @example toTitleCase('hello world') // 'Hello World'
 */
function toTitleCase<T extends string>(str: T): TitleCase<T> {
  return toDelimiterCase(toPascalCase(str), ' ')
}

export type {
  CamelCase,
  ConstantCase,
  DelimiterCase,
  KebabCase,
  PascalCase,
  SnakeCase,
  TitleCase,
}
export {
  capitalize,
  toCamelCase,
  toConstantCase,
  toDelimiterCase,
  toKebabCase,
  toLowerCase,
  toPascalCase,
  toSnakeCase,
  toTitleCase,
  toUpperCase,
}
